  invalid_receipt: { class: 'server', summary: "A company-source ingestion receipt input failed validation inside gbrain; nothing was written.", docs: 'docs/guides/company-brain-ingestion.md#resume-and-verify' },
  invalid_receipt_transition: { class: 'caller', summary: "An ingestion receipt cannot skip a phase or complete while files failed, writes are pending or verification failed.", docs: 'docs/guides/company-brain-ingestion.md#resume-and-verify' },
  invalid_request: { class: 'caller', summary: "submit_agent over the local CLI: use `gbrain agent run` instead." },
